<?php namespace App\Services; use App\Models\{Document,NumberingRule}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class NumberingService { public function assign(Document $document): string { if($document->number)return $document->number; return DB::transaction(function()use($document){$rule=NumberingRule::where('document_type_id',$document->document_type_id)->where(fn($q)=>$q->whereNull('unit_id')->orWhere('unit_id',$document->unit_id))->where('is_active',true)->orderByRaw('unit_id is null')->lockForUpdate()->first(); if(!$rule)throw ValidationException::withMessages(['number'=>'Aturan nomor surat belum tersedia.']); $period=$rule->reset_period==='MONTHLY'?now()->format('Y-m'):now()->format('Y'); DB::table('numbering_sequences')->insertOrIgnore(['numbering_rule_id'=>$rule->id,'period_key'=>$period,'last_value'=>0,'created_at'=>now(),'updated_at'=>now()]); $sequence=DB::table('numbering_sequences')->where('numbering_rule_id',$rule->id)->where('period_key',$period)->lockForUpdate()->first(); $next=$sequence->last_value+1; DB::table('numbering_sequences')->where('id',$sequence->id)->update(['last_value'=>$next,'updated_at'=>now()]); $unit=$document->unit?->code ?? 'PUSAT'; $type=$document->type?->code ?? 'DOC'; $roman=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][now()->month-1]; $number=strtr($rule->format,['{SEQ}'=>str_pad((string)$next,3,'0',STR_PAD_LEFT),'{UNIT}'=>$unit,'{DOCUMENT_TYPE}'=>$type,'{MONTH}'=>now()->format('m'),'{ROMAN_MONTH}'=>$roman,'{YEAR}'=>now()->format('Y')]); $document->update(['number'=>$number,'document_date'=>$document->document_date ?? now()]); return $number;});} }
